    'demo.dots': 'Select a demo step', 'demo.goto': 'Go to step {step}', 'demo.previous': 'Previous', 'demo.next': 'Next', 'demo.keyboard': 'Use the arrow keys to navigate.', 'demo.swipe': 'Swipe to continue', 'demo.cta': 'Start my route', 'demo.imageError': 'This screen could not be loaded.',
    'pain.kicker': 'When life changes', 'pain.title': 'You do not need another perfect plan.', 'pain.complement': 'You need a route that keeps working when your life changes.', 'pain.body': 'Busy schedules, fatigue, unexpected events, meals outside the plan, and missed workouts are part of life. REROUTE helps you adjust the path without turning one difficult day into giving up.',
    'pain.item1': 'Without guilt', 'pain.item2': 'Without starting from zero', 'pain.item3': 'Without relying on a perfect routine', 'pain.item4': 'With realistic adjustments that keep you moving forward',
    'audience.kicker': 'Who it is for', 'audience.title': 'REROUTE was created for people who...', 'audience.lead': 'For people who want to lose weight with a realistic routine, closer support, and adjustments when life changes.',
    'audience.title1': 'Try to lose weight but lose consistency', 'audience.body1': 'They start motivated but struggle to maintain momentum over the weeks.',
    'audience.title2': 'Give up when their routine changes', 'audience.body2': 'An unexpected event disrupts the plan and makes all progress feel lost.',
    'audience.title3': 'Do not know how to organize the day', 'audience.body3': 'They need to connect training, nutrition, and hydration without making life more demanding.',
    'audience.title4': 'Need closer day-to-day support', 'audience.body4': 'They want to see the next step and understand what to adjust each day.',
    'audience.title5': 'Want to preserve strength and muscle mass', 'audience.body5': 'They are losing weight and want to structure training and routine to support physical capacity.',
    'audience.title6': 'Want to rebuild muscle mass and energy', 'audience.body6': 'They have lost weight and want a progressive routine to feel stronger and more active again.',
