const languageOptions = {
  pt: { label: 'PT', name: 'Português', lang: 'pt-BR', countryLocale: 'pt-BR' },
  es: { label: 'ES', name: 'Español', lang: 'es', countryLocale: 'es' },
  en: { label: 'EN', name: 'English', lang: 'en', countryLocale: 'en' }
};

const languageFlags = {
  pt: '<svg class="language-flag" viewBox="0 0 24 16" aria-hidden="true"><rect width="24" height="16" rx="2" fill="#009b3a"/><path d="M12 2.2 21 8l-9 5.8L3 8Z" fill="#ffdf00"/><circle cx="12" cy="8" r="3.1" fill="#002776"/></svg>',
  es: '<svg class="language-flag" viewBox="0 0 24 16" aria-hidden="true"><rect width="24" height="16" rx="2" fill="#aa151b"/><path d="M0 4h24v8H0Z" fill="#f1bf00"/></svg>',
  en: '<svg class="language-flag" viewBox="0 0 24 16" aria-hidden="true"><rect width="24" height="16" rx="2" fill="#fff"/><path d="M0 0h24v2H0Zm0 4h24v2H0Zm0 4h24v2H0Zm0 4h24v2H0Z" fill="#b22234"/><path d="M0 0h10v8H0Z" fill="#3c3b6e"/><g fill="#fff"><circle cx="2" cy="2" r=".55"/><circle cx="5" cy="2" r=".55"/><circle cx="8" cy="2" r=".55"/><circle cx="3.5" cy="4" r=".55"/><circle cx="6.5" cy="4" r=".55"/><circle cx="2" cy="6" r=".55"/><circle cx="5" cy="6" r=".55"/><circle cx="8" cy="6" r=".55"/></g></svg>'
};

const LANGUAGE_STORAGE_KEY = 'reroute-language';
const DEFAULT_LANGUAGE = 'pt';

const getStoredLanguage = () => {
  try {
    const stored = localStorage.getItem(LANGUAGE_STORAGE_KEY);
    return languageOptions[stored] ? stored : null;
  } catch {
    return null;
  }
};

const savedLanguage = getStoredLanguage();
let currentLanguage = savedLanguage || DEFAULT_LANGUAGE;
const translate = (key) => translations[currentLanguage]?.[key] ?? translations.pt[key] ?? key;

const persistLanguage = (language) => {
  try {
    localStorage.setItem(LANGUAGE_STORAGE_KEY, language);
  } catch {
    // The selected language remains active for the current session when storage is unavailable.
  }
};

const renderLanguageSwitcher = (container) => {
  const active = languageOptions[currentLanguage];
  container.innerHTML = `
    <button class="language-switcher__trigger" type="button" aria-label="${translate('language.label')}" aria-haspopup="true" aria-expanded="false">
      ${languageFlags[currentLanguage]}<strong>${active.label}</strong><span class="language-switcher__chevron" aria-hidden="true">⌄</span>
    </button>
    <div class="language-switcher__menu" role="menu" aria-label="${translate('language.menu')}" hidden>
      ${Object.entries(languageOptions).map(([code, option]) => `
        <button type="button" role="menuitemradio" aria-checked="${code === currentLanguage}" data-language="${code}">
          ${languageFlags[code]}<span class="language-switcher__name">${option.name}</span><strong class="language-switcher__code">${option.label}</strong>
        </button>
      `).join('')}
    </div>`;
};

const updateTourAccessibility = () => {
  const captions = Array.from({ length: 6 }, (_, index) => translate(`tour.caption${index + 1}`));
  document.querySelectorAll('[data-product-tour-slide]').forEach((slide, index) => {
    slide.setAttribute('aria-label', `${index + 1} ${currentLanguage === 'en' ? 'of' : currentLanguage === 'es' ? 'de' : 'de'} 6`);
  });
  document.querySelectorAll('[data-product-tour-dot]').forEach((dot, index) => {
    const prefix = currentLanguage === 'en' ? 'Go to screen' : currentLanguage === 'es' ? 'Ir a la pantalla' : 'Ir para a tela';
    dot.setAttribute('aria-label', `${prefix} ${index + 1}: ${captions[index]}`);
  });
};

const applyLanguage = (language, { persist = true } = {}) => {
  const nextLanguage = languageOptions[language] ? language : currentLanguage;
  currentLanguage = nextLanguage;

  if (persist) {
    persistLanguage(currentLanguage);
  }

  document.documentElement.lang = languageOptions[currentLanguage].lang;
  document.title = translate('meta.title');
  document.querySelector('meta[name="description"]')?.setAttribute('content', translate('meta.description'));

  textBindings.forEach(([selector, key, mode]) => {
    document.querySelectorAll(selector).forEach((element) => {
      if (mode === 'caption') {
        const number = element.querySelector('span')?.outerHTML || '';
        element.innerHTML = `${number}${translate(key)}`;
      } else {
        element.textContent = translate(key);
      }
    });
  });
  htmlBindings.forEach(([selector, key]) => document.querySelectorAll(selector).forEach((element) => { element.innerHTML = translate(key); }));
  attributeBindings.forEach(([selector, attribute, key]) => document.querySelectorAll(selector).forEach((element) => element.setAttribute(attribute, translate(key))));
  updateTourAccessibility();

  document.querySelectorAll('[data-language-switcher]').forEach(renderLanguageSwitcher);
  document.querySelector('[data-menu-toggle]')?.setAttribute('aria-label', translate('nav.open'));

  window.dispatchEvent(new CustomEvent('reroute:languagechange', { detail: { language: currentLanguage } }));
};

document.addEventListener('click', (event) => {
  const trigger = event.target.closest('.language-switcher__trigger');
  const option = event.target.closest('[data-language]');

  if (trigger) {
    const switcher = trigger.closest('[data-language-switcher]');
    const menu = switcher.querySelector('.language-switcher__menu');
    const open = menu.hidden;
    document.querySelectorAll('.language-switcher__menu').forEach((item) => { item.hidden = true; });
    document.querySelectorAll('.language-switcher__trigger').forEach((item) => item.setAttribute('aria-expanded', 'false'));
    menu.hidden = !open;
    trigger.setAttribute('aria-expanded', String(open));
    if (open) menu.querySelector('[aria-checked="true"]')?.focus();
    return;
  }

  if (option) {
    event.preventDefault();
    applyLanguage(option.dataset.language);
    return;
  }

  document.querySelectorAll('.language-switcher__menu').forEach((menu) => { menu.hidden = true; });
  document.querySelectorAll('.language-switcher__trigger').forEach((item) => item.setAttribute('aria-expanded', 'false'));
});

document.addEventListener('keydown', (event) => {
  if (event.key === 'Escape') {
    document.querySelectorAll('.language-switcher__menu').forEach((menu) => { menu.hidden = true; });
    document.querySelectorAll('.language-switcher__trigger').forEach((item) => item.setAttribute('aria-expanded', 'false'));
  }
});

window.rerouteI18n = {
  applyLanguage,
  getLanguage: () => currentLanguage,
  getCountryLocale: () => languageOptions[currentLanguage].countryLocale,
  t: translate,
  translationCount: Object.keys(translations.pt).length
};

applyLanguage(currentLanguage, { persist: false });
